python3 -c "
import re
import os

for root, dirs, files in os.walk('src/runner'):
    for f in files:
        if not f.endswith('.rs'):
            continue
        path = os.path.join(root, f)
        with open(path) as fh:
            lines = fh.readlines()
        in_test = False
        for i, line in enumerate(lines, 1):
            if '#[cfg(test)]' in line:
                in_test = True
            if in_test:
                continue
            if '.unwrap()' in line and not line.strip().startswith('//'):
                print(f'{path}:{i}: {line.rstrip()}')
"

